func remainingWaitBudget(timeout, elapsed time.Duration) time.Duration {
	if timeout <= 0 {
		return blaxelWaitUnlimited
	}
	remaining := timeout - elapsed
	if remaining <= 0 {
		return 0
	}
	return remaining
